"""Parse skill.md prose into always-visible and ``if:``-scoped instruction segments.

Prose markers are compile-time only. ``else:`` / ``elif:`` are not allowed in
prose — use separate ``if:`` paragraphs, or an ordered block for true if/else
branching (:class:`~rasa.exceptions.ValidationError`).

"""

from __future__ import annotations

import re
from typing import Any, Sequence

import structlog
from pydantic import BaseModel, ConfigDict

from rasa.exceptions import ValidationError
from rasa.mantle.skills.conditions import (
    Condition,
    ConditionEvaluationError,
    evaluate_expression,
)

structlogger = structlog.get_logger()

_UNSUPPORTED_ELSE_CODE = "skill.markdown.unsupported_prose_else"
_UNSUPPORTED_ELIF_CODE = "skill.markdown.unsupported_prose_elif"
_EMPTY_IF_BODY_CODE = "skill.markdown.empty_prose_if_body"
_EMPTY_IF_CONDITION_CODE = "skill.markdown.empty_prose_if_condition"

# Blank lines separate paragraph units. Use horizontal whitespace only between
# newlines (``[^\S\n]``) so ``\s`` cannot overlap ``\n`` and trigger Sonar
# backtracking warnings.
_PARAGRAPH_SPLIT = re.compile(r"\n[^\S\n]*\n+")
# Separator between visible instruction paragraphs (join + prompt render).
_INSTRUCTION_PARAGRAPH_SEPARATOR = "\n\n"

_ELSE_MARKER = "else:"
_ELIF_MARKER = "elif:"
_IF_MARKER = "if:"


class ProseSegment(BaseModel):
    """One instruction paragraph for the active-skill prompt.

    When ``condition`` is ``None`` the paragraph is always visible. Otherwise it
    is included only when ``condition`` evaluates true against current memory.

    Conditional ``if:`` paragraphs are **not** compiled into separate activation
    targets — they filter which prose text is shown each turn while the prose
    entry (compiled target id equals ``skill.id``) is active.
    """

    model_config = ConfigDict(frozen=True)

    text: str
    condition: Condition | None = None


def render_visible_instructions(
    segments: Sequence[ProseSegment],
    memory_values: dict[str, Any],
) -> str:
    """Filter instruction segments for the current turn's memory values.

    Always-visible segments are included. Conditional ``if:`` segments are
    included only when ``evaluate_expression`` returns true. Evaluation errors
    omit that segment (same fail-closed stance as skill ``requires`` gating).

    When *segments* is empty, returns an empty string (blocks-only skills and
    ordered-block active frames omit skill-level prose).
    """
    if not segments:
        return ""

    visible: list[str] = []
    for segment in segments:
        if segment.condition is None:
            visible.append(segment.text)
            continue
        try:
            include = bool(evaluate_expression(segment.condition, memory_values))
        except ConditionEvaluationError as exc:
            structlogger.debug(
                "mantle.prose_scoping.condition_evaluation_failed",
                condition=segment.condition,
                error=str(exc),
            )
            include = False
        if include:
            visible.append(segment.text)
    return _INSTRUCTION_PARAGRAPH_SEPARATOR.join(visible)


def parse_prose_instruction_segments(prose: str) -> list[ProseSegment]:
    """Parse skill.md prose (ordered blocks already stripped) into segments.

    Args:
        prose: Markdown prose outside ``:::ordered_block`` sections.

    Returns:
        Ordered segments. Empty input yields an empty list.

    Raises:
        ValidationError: On ``else:`` / ``elif:``, empty ``if:`` condition, or
            empty body after ``if:``.
    """
    stripped = prose.strip()
    if not stripped:
        return []

    # Split on blank lines; each unit becomes one ProseSegment (condition None or set).
    return [_parse_paragraph_unit(unit) for unit in _PARAGRAPH_SPLIT.split(stripped)]


def is_empty_prose_if_condition(condition: str) -> bool:
    """Return whether a prose ``if:`` condition is missing or whitespace-only.

    Shared by compile-time parsing and train-time
    :func:`~rasa.mantle.skills.validation.validate_prose_instruction_scopes`
    so both gates agree on emptiness.
    """
    return not condition.strip()


def _parse_paragraph_unit(unit: str) -> ProseSegment:
    """Classify one blank-line-delimited paragraph into a :class:`ProseSegment`.

    Plain prose yields ``condition=None``; a leading ``if:`` line yields a
    condition plus body text. Example unit::

        if: session.card_replace.replacement_reason == 'stolen'
        Lock the card immediately.

    becomes:

        ProseSegment(
            text='Lock the card immediately.',
            condition="session.card_replace.replacement_reason == 'stolen'",
        )
    """
    lines = unit.splitlines()
    first = lines[0].strip()

    _reject_unsupported_prose_branch_marker(first)

    if_condition = _if_marker_condition(first)
    if if_condition is not None:
        # Text after ``if:`` must be a non-empty expression.
        _require_non_empty_prose_if_condition(if_condition)
        # Remaining lines are the paragraph body shown when the condition is true.
        body = "\n".join(lines[1:]).strip()
        # Body under the ``if:`` line must be non-empty; otherwise ValidationError.
        _require_non_empty_prose_if_body(body)
        return ProseSegment(text=body, condition=if_condition)

    return ProseSegment(text=unit.strip())


def _reject_unsupported_prose_branch_marker(first_line: str) -> None:
    """Raise when a paragraph starts with prose ``else:`` / ``elif:``.

    Exclusive branching is not supported in skill-level prose — authors should
    use separate ``if:`` paragraphs or an ordered block. Compile-time only;
    train-time validation never sees these markers because the skill fails to
    load first.
    """
    if first_line.startswith(_ELSE_MARKER):
        raise ValidationError(
            code=_UNSUPPORTED_ELSE_CODE,
            event_info=(
                "'else:' is not allowed in prose. Prefer separate 'if:' "
                "paragraphs for each case, or use an ordered block for true "
                "if/else branching."
            ),
        )

    if first_line.startswith(_ELIF_MARKER):
        raise ValidationError(
            code=_UNSUPPORTED_ELIF_CODE,
            event_info=(
                "'elif:' is not allowed in prose. Prefer separate 'if:' "
                "paragraphs for each case, or use an ordered block for true "
                "if/else branching."
            ),
        )


def _if_marker_condition(first_line: str) -> str | None:
    """Return the stripped ``if:`` condition when *first_line* is a marker.

    Returns an empty string when the marker has no condition text. Returns
    ``None`` when the line is not an ``if:`` marker.

    Examples:
        ``"if: session.foo == 1"`` → ``"session.foo == 1"``
        ``"if:"`` / ``"if:   "`` → ``""``
        ``"Ask the user…"`` → ``None``
    """
    if not first_line.startswith(_IF_MARKER):
        return None
    return first_line[len(_IF_MARKER) :].strip()


def _require_non_empty_prose_if_condition(condition: str) -> None:
    """Raise :class:`ValidationError` when a prose ``if:`` condition is empty."""
    if is_empty_prose_if_condition(condition):
        raise ValidationError(
            code=_EMPTY_IF_CONDITION_CODE,
            event_info="Prose 'if:' marker must include a non-empty condition.",
        )


def _require_non_empty_prose_if_body(body: str) -> None:
    """Raise :class:`ValidationError` when a prose ``if:`` body is empty."""
    if not body:
        raise ValidationError(
            code=_EMPTY_IF_BODY_CODE,
            event_info=(
                "Prose 'if:' marker must be followed by a non-empty paragraph body."
            ),
        )
